const listWikiPagesForMember = `-- name: ListWikiPagesForMember :many
WITH search_input AS MATERIALIZED (
  SELECT ('(' || string_agg(quote, ' & ') || ') | '
    || '''' || replace(replace(lower(btrim($7::text)), '\', '\\'), '''', '''''') || ''':*')::tsquery AS query
  FROM unnest(to_tsvector('simple', $7::text)) AS token(lexeme),
    LATERAL (SELECT '''' || replace(replace(lexeme, '\', '\\'), '''', '''''') || ''':*') AS quoted(quote)
)
SELECT p.id, p.company_id,
 display_collection.id AS collection_id,
 p.slug, (CASE WHEN p.current_revision_id IS NULL THEN COALESCE(d.title,p.title) ELSE p.title END)::text AS title,
 (CASE WHEN p.current_revision_id IS NULL THEN COALESCE(d.summary,p.summary) ELSE p.summary END)::text AS summary,
  p.status, p.version, p.created_at, p.updated_at, (p.current_revision_id IS NOT NULL)::boolean AS published,
  EXISTS(SELECT 1 FROM wiki_favorites f WHERE f.company_id = p.company_id
    AND f.page_id = p.id AND f.user_id = $1::uuid)::boolean AS favorite
FROM company_wiki_pages p
LEFT JOIN wiki_canvas_drafts d ON d.company_id=p.company_id AND d.page_id=p.id
LEFT JOIN wiki_collections display_collection ON display_collection.company_id=p.company_id
 AND display_collection.id=CASE WHEN p.current_revision_id IS NULL THEN d.collection_id ELSE p.collection_id END
JOIN company_members actor ON actor.company_id = p.company_id
  AND actor.user_id = $1::uuid AND actor.status = 'active'
WHERE (p.current_revision_id IS NOT NULL OR actor.role=ANY($2::text[]))
  AND p.company_id = $3::uuid
  AND p.status = $4::text
  AND ($5::uuid IS NULL OR CASE WHEN p.current_revision_id IS NULL THEN d.collection_id ELSE p.collection_id END = $5::uuid)
  AND (NOT $6::boolean OR EXISTS(
    SELECT 1 FROM wiki_favorites f WHERE f.company_id = p.company_id
      AND f.page_id = p.id AND f.user_id = $1::uuid))
  AND (length(to_tsvector('simple', $7::text)) = 0
    OR p.search_vector @@ (SELECT query FROM search_input)
    OR (p.current_revision_id IS NULL AND to_tsvector('simple',d.title || ' ' || d.markdown) @@ (SELECT query FROM search_input)))
ORDER BY
  -- A search ranks first (title A, summary B, body C) and falls
  -- back to recency; browsing keeps the recency order. A draft has no stored
  -- vector, so it is ranked on the same weights computed from its own text.
  -- The browse arm is a constant the planner folds away, so the ordered index
  -- still serves it.
  CASE WHEN length(to_tsvector('simple', $7::text)) = 0 THEN 0::real
    ELSE COALESCE(ts_rank(
      CASE WHEN p.current_revision_id IS NULL
        THEN setweight(to_tsvector('simple', d.title), 'A') || setweight(to_tsvector('simple', d.summary), 'B')
          || setweight(to_tsvector('simple', d.markdown), 'C')
        ELSE p.search_vector END,
      (SELECT query FROM search_input)), 0::real) END DESC,
  p.updated_at DESC, p.id DESC
LIMIT $9::int OFFSET $8::int
`

